              </div>
            </div>
          ) : (
            <div className="surface" style={{height: 'calc(100vh - 240px)', padding: 0, overflow: 'hidden'}}>
              <FrameMap frames={filtered} activeId={selectedId} onPick={onOpen} />
            </div>
          )}
        </section>
      </div>
    </React.Fragment>
  );
}

